package main

import (
	"flag"
	"fmt"
	"os"
	"runtime"
	"time"

	"example.com/syscallcli/internal/platform"
)

func main() {
	verbose := flag.Bool("v", false, "print build target details")
	flag.Parse()

	up, err := platform.Uptime()
	if err != nil {
		fmt.Fprintf(os.Stderr, "syscallcli: uptime: %v\n", err)
		os.Exit(1)
	}

	if *verbose {
		fmt.Printf("target: %s/%s\n", runtime.GOOS, runtime.GOARCH)
	}
	fmt.Printf("uptime: %s\n", up.Round(time.Second))
}

// Package platform provides thin wrappers around operating system calls that
// the Go standard library does not expose in a portable way.
//
// The exported surface is defined once here and implemented in build-tagged
// files per GOOS. Because the golang.org/x/sys packages are pure Go, these
// calls can be cross-compiled from any host with CGO_ENABLED=0; no cgo and no
// platform toolchain is required.
package platform

import "time"

// Uptime reports how long the system has been running.
func Uptime() (time.Duration, error)

// Package platform provides thin wrappers around operating system calls that
// the Go standard library does not expose in a portable way.
//
// The contract for each entry point is documented below and implemented in
// build-tagged files per GOOS. Because the golang.org/x/sys packages are pure
// Go, these calls cross-compile from any host with CGO_ENABLED=0; no cgo and no
// platform toolchain is required.
//
//	func Uptime() (time.Duration, error)
//
// Uptime reports how long the system has been running.
package platform

//go:build linux

package platform

import (
	"time"

	"golang.org/x/sys/unix"
)

// Uptime reads the sysinfo(2) syscall directly. The standard library exposes
// neither sysinfo nor the raw system uptime, so this drops to x/sys/unix.
func Uptime() (time.Duration, error) {
	var info unix.Sysinfo_t
	if err := unix.Sysinfo(&info); err != nil {
		return 0, err
	}
	return time.Duration(info.Uptime) * time.Second, nil
}

//go:build darwin

package platform

import (
	"time"

	"golang.org/x/sys/unix"
)

// Uptime reads kern.boottime via sysctl(3), which the standard library does not
// expose, then subtracts it from the current time.
func Uptime() (time.Duration, error) {
	tv, err := unix.SysctlTimeval("kern.boottime")
	if err != nil {
		return 0, err
	}
	boot := time.Unix(tv.Sec, int64(tv.Usec)*1000)
	return time.Since(boot), nil
}

//go:build windows

package platform

import (
	"time"

	"golang.org/x/sys/windows"
)

// kernel32 procedures are resolved lazily so the process only binds the symbols
// it actually uses. GetTickCount64 is not surfaced by the standard library.
var (
	kernel32         = windows.NewLazySystemDLL("kernel32.dll")
	procGetTickCount = kernel32.NewProc("GetTickCount64")
)

// Uptime calls GetTickCount64, which returns milliseconds since boot and never
// fails.
func Uptime() (time.Duration, error) {
	ms, _, _ := procGetTickCount.Call()
	return time.Duration(ms) * time.Millisecond, nil
}

//go:build !linux && !darwin && !windows

package platform

import (
	"errors"
	"time"
)

// ErrUnsupported is returned on platforms without an implementation.
var ErrUnsupported = errors.New("platform: uptime is not implemented on this GOOS")

// Uptime is unavailable on this platform.
func Uptime() (time.Duration, error) {
	return 0, ErrUnsupported
}

